def find_path(graph, start, goal):
    # Depth-First Search
    def dfs_search(graph, start, goal, path=None):
        if path is None:
            path = [start]
        if start == goal:
            return path
        for neighbor in graph[start]:
            if neighbor not in path:
                new_path = dfs_search(graph, neighbor, goal, path + [neighbor])
                if new_path:
                    return new_path
        return None

    # Breadth-First Search
    def bfs_search(graph, start, goal):
        queue = [[start]]
        while queue:
            path = queue.pop(0)
            node = path[-1]
            if node == goal:
                return path
            for neighbor in graph.get(node, []):
                new_path = list(path)
                new_path.append(neighbor)
                queue.append(new_path)
        return None

    # Check if the goal is reachable
    reachable = any(bfs_search(graph, start, goal) is not None)
    if not reachable:
        return None

    # Use either DFS or BFS to find the path
    # Here we use DFS as an example, but BFS would be more appropriate for this function
    return dfs_search(graph, start, goal)

